// Graphics for Blitz programs: a window from SDL3, and everything drawn through Vulkan.
//
// Blitz draws immediately, so drawing commands are collected into a list of operations for the current buffer, and
// that list is replayed on the GPU when it matters: on Flip, when the buffer changes, or when the program waits.
// There are two buffers, like in Blitz: the back buffer that programs usually draw to, and the front buffer that is
// shown in the window. Flip copies the back buffer to the front buffer and presents the result.
//
// SDL loads the Vulkan loader for us, and all Vulkan functions are fetched through it, so there is nothing to link.
//
// Set BLITZ_HEADLESS=1 to run programs without creating a window, in which case graphics commands do nothing.

#define VK_NO_PROTOTYPES
#include <vulkan/vulkan.h>

#include <SDL3/SDL.h>
#include <SDL3/SDL_vulkan.h>
#include <SDL3_image/SDL_image.h>

#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "scene.hpp"
#include "font8x8.inc"
#include "shaders.inc"

