// LoadTexture(file, flags): flags are 1 = color, 2 = alpha channel, 4 = masked (black is transparent), 16/32 = clamp U/V.
int32_t bb_load_texture(const char* file, int32_t flags)
{
	if (!file) {
		return 0;
	}
	SDL_Surface* loaded = IMG_Load(file);
	if (!loaded) {
		return 0; // Blitz gives 0 for missing files.
	}
	SDL_Surface* rgba = SDL_ConvertSurface(loaded, SDL_PIXELFORMAT_RGBA32);
	SDL_DestroySurface(loaded);
	if (!rgba) {
		return 0;
	}

	// Without the alpha flag, the image's own alpha is ignored. Masked textures treat black as transparent.
	for (int y = 0; y < rgba->h; y++) {
		uint8_t* row = static_cast<uint8_t*>(rgba->pixels) + size_t(y) * size_t(rgba->pitch);
		for (int x = 0; x < rgba->w; x++) {
			uint8_t* px = row + x * 4;
			if (flags & TEXTURE_MASKED) {
				px[3] = (px[0] || px[1] || px[2]) ? 255 : 0;
			} else if (!(flags & TEXTURE_ALPHA)) {
				px[3] = 255;
			}
		}
	}

	texture_entry entry;
	entry.used   = true;
	entry.flags  = flags;
	entry.width  = rgba->w;
	entry.height = rgba->h;
	if (active()) {
		VkSampler sampler = ((flags & TEXTURE_CLAMP_U) || (flags & TEXTURE_CLAMP_V)) ? g.sampler_clamp : g.sampler_repeat;
		upload_texture(entry.image, entry.set, uint32_t(rgba->w), uint32_t(rgba->h), static_cast<const uint8_t*>(rgba->pixels), sampler);
	}
	SDL_DestroySurface(rgba);

	for (uint32_t i = 0; i < texture_table.size; i++) {
		if (!texture_table[i].used) {
			texture_table[i] = entry;
			return int32_t(i) + 1;
		}
	}
	texture_table.push(entry);
	return int32_t(texture_table.size);
}

void bb_free_texture(int32_t handle)
{
	texture_entry* t = texture_of(handle);
	if (!t) {
		bb_runtime_error("FreeTexture: texture does not exist.");
	}
	free_texture(*t);
}

int32_t bb_texture_width(int32_t handle)
{
	texture_entry* t = texture_of(handle);
	return t ? t->width : 0;
}

int32_t bb_texture_height(int32_t handle)
{
	texture_entry* t = texture_of(handle);
	return t ? t->height : 0;
}

// RenderWorld: draws everything the cameras see into the current buffer.
void bb_render_world(float tween)
{
	(void)tween;
	if (!active()) {
		return;
	}
	flush(); // Whatever was drawn before comes first.
	g.triangles_drawn = 0;

	scene_data data = {};
	data.ambient[0] = bb::ambient_light[0];
	data.ambient[1] = bb::ambient_light[1];
	data.ambient[2] = bb::ambient_light[2];
	data.ambient[3] = 1;
	light_collector lights = { &data, 0 };
	bb::for_each_visible(bb::LIGHT, collect_light, &lights);

	camera_collector cameras;
	bb::for_each_visible(bb::CAMERA, collect_camera, &cameras);
	for (uint32_t i = 0; i < cameras.handles.size; i++) {
		bb::entity* cam = bb::get_entity(cameras.handles[i]);
		if (cam) {
			render_camera(cameras.handles[i], *cam, data);
		}
	}
	cameras.handles.release();
}

// The scene lets go of a surface: its GPU buffers go with it.
void bb_release_surface_gpu(void* gpu)
{
	if (gpu && g.device) {
		release_surface_gpu(static_cast<surface_gpu*>(gpu));
	}
}

// Called by Delay, so programs that wait keep their window alive and showing what they drew.
void bb_graphics_idle(void)
{
	bb_sound_update();
	if (active()) {
		flush();
		pump();
	}
}
